// Exact arithmetic for the agent. Input: an expression such as 3*12500 + 2*9000
const src = String(query).replace(/[,₦\s]/g, '');
if (!/^[0-9+\-*/().]+$/.test(src)) return 'Error: use only numbers and + - * / ( )';
let i = 0;
const num = () => { const m = src.slice(i).match(/^\d+(\.\d+)?/); if (!m) throw new Error('bad number'); i += m[0].length; return Number(m[0]); };
const factor = () => {
  if (src[i] === '-') { i++; return -factor(); }
  if (src[i] === '(') { i++; const v = expr(); if (src[i] !== ')') throw new Error('missing )'); i++; return v; }
  return num();
};
const term = () => { let v = factor(); while (src[i] === '*' || src[i] === '/') { const op = src[i++]; const r = factor(); v = op === '*' ? v * r : v / r; } return v; };
const expr = () => { let v = term(); while (src[i] === '+' || src[i] === '-') { const op = src[i++]; const r = term(); v = op === '+' ? v + r : v - r; } return v; };
try { const v = expr(); if (i !== src.length) throw new Error('unexpected ' + src[i]); return String(Math.round(v * 100) / 100); }
catch (e) { return 'Error: ' + e.message; }
